// Revenue conversion fix: ensure paidEvents increments on successful checkout
// This module intercepts the checkout completion event and updates the revenue counter.

const fs = require('fs');
const path = require('path');

const REVENUE_FILE = path.join(__dirname, '..', 'data', 'revenue.json');

function ensureRevenueFile() {
  if (!fs.existsSync(path.dirname(REVENUE_FILE))) {
    fs.mkdirSync(path.dirname(REVENUE_FILE), { recursive: true });
  }
  if (!fs.existsSync(REVENUE_FILE)) {
    fs.writeFileSync(REVENUE_FILE, JSON.stringify({ paidEvents: 0, conversionRate: 0, leads: 0 }));
  }
}

function incrementPaidEvents() {
  ensureRevenueFile();
  const data = JSON.parse(fs.readFileSync(REVENUE_FILE, 'utf8'));
  data.paidEvents = (data.paidEvents || 0) + 1;
  data.conversionRate = data.leads > 0 ? (data.paidEvents / data.leads) * 100 : 0;
  fs.writeFileSync(REVENUE_FILE, JSON.stringify(data, null, 2));
  console.log(`Revenue conversion: paidEvents incremented to ${data.paidEvents}`);
}

// Hook into checkout completion (assumes event emitter or webhook)
// For now, expose function to be called by checkout success handler
module.exports = { incrementPaidEvents };
